-- Применение перевода ко всем элементам
function TPT_RUS.ApplyElements()
    local count = 0
    for ident, data in pairs(TPT_RUS.ELEMENTS) do
        local id = data.id
        if elem and elem.exists and elem.exists(id) then
            elem.property(id, "Description", data.desc)
            if TPT_RUS.TRANSLATE_BUTTONS and data.short_ru and #data.short_ru > 0 then
                elem.property(id, "Name", data.short_ru)
            end
            count = count + 1
        end
    end
    return count
end

-- Скрываем стандартный английский экран приветствия
if ren and ren.hud then
    ren.hud(false)
    ren.hud(true)
end

TPT_RUS.show_help = false
TPT_RUS.welcome_timer = 360 -- ~6 секунд при 60 FPS

-- Обработчик горячих клавиш: F1 для справки
event.register(event.KEYPRESS, function(key, scan, rep, shift, ctrl, alt)
    if scan == 58 or scan == 1073741882 or key == 282 or key == "f1" or key == 58 then
        TPT_RUS.show_help = not TPT_RUS.show_help
        return false
    end
    if key == 27 and TPT_RUS.show_help then
        TPT_RUS.show_help = false
        return false
    end
end)

-- Обработчик клика мыши: кнопка [РУС] вверху слева или закрытие справки
event.register(event.MOUSEDOWN, function(mx, my, btn)
    -- Закрываем баннер приветствия при любом клике по экрану
    if TPT_RUS.welcome_timer > 0 and my > 45 and not TPT_RUS.show_help then
        TPT_RUS.welcome_timer = 0
    end
    -- Кнопка [РУС] Справка (x: 90..166, y: 4..18) - смещена вправо, чтобы не перекрывать счетчик FPS
    if mx >= 90 and mx <= 166 and my >= 4 and my <= 18 then
        TPT_RUS.show_help = not TPT_RUS.show_help
        return false
    end
    -- Клик по кнопке закрытия справки внутри окна
    if TPT_RUS.show_help then
        local w, h = 574, 344
        local x = math.floor((sim.XRES - w) / 2)
        local y = 20
        if mx >= x + w - 95 and mx <= x + w - 5 and my >= y + 3 and my <= y + 17 then
            TPT_RUS.show_help = false
            return false
        end
    end
end)

-- Отрисовка графического интерфейса русификатора
event.register(event.AFTERSIMDRAW, function()
    -- 1. Кнопка [РУС] Справка (x: 90, y: 4) рядом со счетчиком FPS (x: 10..76)
    gfx.fillRect(90, 4, 76, 14, 20, 30, 45, 230)
    gfx.drawRect(90, 4, 76, 14, 60, 140, 220, 255)
    gfx.drawText(94, 8, "[РУС] Справка", 160, 220, 255, 255)

    -- 2. Приветственный баннер при запуске игры (смещен на строку ниже y: 22)
    if TPT_RUS.welcome_timer > 0 then
        TPT_RUS.welcome_timer = TPT_RUS.welcome_timer - 1
        local alpha = 255
        if TPT_RUS.welcome_timer < 50 then
            alpha = math.floor(TPT_RUS.welcome_timer * 255 / 50)
        end
        local bx, by, bw, bh = 10, 22, 420, 14
        gfx.fillRect(bx, by, bw, bh, 15, 25, 35, math.floor(alpha * 0.9))
        gfx.drawRect(bx, by, bw, bh, 50, 150, 230, alpha)
        gfx.drawText(bx + 6, by + 4, "РУСИФИКАТОР АКТИВЕН: 194 элемента переведено! [F1 - Справка]", 120, 230, 255, alpha)
    end

    -- 3. Окно полной русской справки по F1 (непрозрачное)
    if TPT_RUS.show_help then
        local w, h = 574, 344
        local x = math.floor((sim.XRES - w) / 2)
